{  "explanation": "A Galton board drops balls through a triangular array of pegs; at each peg a ball deflects left or right with equal probability, so after n rows its final bin is X = number of right turns. Since X counts 'successes' in n independent fair coin flips, X ~ Binomial(n, 1/2), and the ball stacks converge to the predicted curve P(X=k) = C(n,k)/2^n — a beautiful demonstration of the central limit theorem in action. Use the controls to start the flow of balls, change the number of rows, adjust speed, or reset.",  "manimCode": "// ===== Galton Board -> Binomial Distribution =====

// ---- State ----
let nRows = 8;
let speed = 1.5;
let running = false;
let balls = [];            // balls currently in flight
let counts = [];           // landed balls per bin
let probs = [];            // binomial probabilities
let totalLanded = 0;
let scaleY = 0.15;         // vertical units per ball in bars
let rowH = 0.45, s = 0.55, y1 = 2.3;
let boardObjs = [];        // pegs, dividers, labels, bars...
let bars = [], curveSegs = [];
let spawnTimer = 0;
let lastTime = null;

const binBottomY = -2.6;
const barAreaH = 1.2;
const dividerTopY = -1.05;
const binLevelY = -1.3;

// ---- Static text ----
const title = new Text({ text: 'The Galton Board', color: WHITE, fontSize: 32 });
title.moveTo([-4.15, 3.3, 0]);

const subtitle = new Text({ text: 'Each ball goes left or right with probability 1/2 at every peg', color: GRAY, fontSize: 16 });
subtitle.moveTo([-3.75, 2.88, 0]);

const legend = new Text({ text: '— binomial prediction', color: YELLOW, fontSize: 18 });
legend.moveTo([4.55, -2.9, 0]);
scene.add(legend);

const formula = new MathTex({ latex: 'P(X=k) = \\binom{n}{k}\\left(\\frac{1}{2}\\right)^{n}', fontSize: 30 });
await formula.waitForRender();
formula.moveTo([0, -3.45, 0]);

let countText = null;
function updateCountText() {
  if (countText) scene.remove(countText);
  countText = new Text({ text: 'Balls dropped: ' + totalLanded, color: WHITE, fontSize: 20 });
  countText.moveTo([-4.35, 2.4, 0]);
  scene.add(countText);
}

function binom(n, k) {
  let c = 1;
  for (let i = 0; i < k; i++) c = c * (n - i) / (i + 1);
  return c;
}

function ballSpeed() { return 2.4 * speed; }

// ---- Board construction ----
function rebuildBoard() {
  for (const m of boardObjs) scene.remove(m);
  boardObjs = [];
  for (const b of balls) scene.remove(b.dot);
  balls = [];
  bars = []; curveSegs = [];
  counts = new Array(nRows + 1).fill(0);
  totalLanded = 0;

  rowH = Math.min(0.5, 3.6 / nRows);
  s = Math.min(0.62, 6.2 / nRows);
  y1 = binLevelY + nRows * rowH;

  probs = [];
  for (let k = 0; k <= nRows; k++) probs.push(binom(nRows, k) / Math.pow(2, nRows));

  // Pegs
  for (let r = 1; r <= nRows; r++) {
    for (let j = 0; j < r; j++) {
      const peg = new Dot({ point: [(j - (r - 1) / 2) * s, y1 - (r - 1) * rowH, 0], radius: 0.05, color: TEAL });
      scene.add(peg); boardObjs.push(peg);
    }
  }

  // Funnel at the top
  const funL = new Polygon({ vertices: [[-0.45, y1 + 0.85, 0], [-0.15, y1 + 0.2, 0]], color: WHITE });
  funL.setStrokeWidth(3).setFillOpacity(0);
  const funR = new Polygon({ vertices: [[0.45, y1 + 0.85, 0], [0.15, y1 + 0.2, 0]], color: WHITE });
  funR.setStrokeWidth(3).setFillOpacity(0);
  scene.add(funL, funR); boardObjs.push(funL, funR);

  // Bin dividers + floor
  for (let m = 0; m <= nRows + 1; m++) {
    const x = (m - (nRows + 1) / 2) * s;
    const div = new Polygon({ vertices: [[x, binBottomY, 0], [x, dividerTopY, 0]], color: GRAY });
    div.setStrokeWidth(2).setFillOpacity(0);
    scene.add(div); boardObjs.push(div);
  }
  const floor = new Polygon({ vertices: [[-(nRows + 1) * s / 2, binBottomY, 0], [(nRows + 1) * s / 2, binBottomY, 0]], color: GRAY });
  floor.setStrokeWidth(2).setFillOpacity(0);
  scene.add(floor); boardObjs.push(floor);

  // Bars, curve segments, bin labels
  for (let k = 0; k <= nRows; k++) {
    const cx = (k - nRows / 2) * s;
    const bar = new Polygon({ vertices: [[cx - 0.4 * s, binBottomY, 0], [cx + 0.4 * s, binBottomY, 0], [cx + 0.4 * s, binBottomY, 0], [cx - 0.4 * s, binBottomY, 0]], color: BLUE });
    bar.setFill(BLUE, 0.65).setStrokeWidth(1);
    scene.add(bar); boardObjs.push(bar); bars.push(bar);

    const lab = new Text({ text: '' + k, color: GRAY, fontSize: 12 });
    lab.moveTo([cx, -2.85, 0]);
    scene.add(lab); boardObjs.push(lab);

    if (k < nRows) {
      const seg = new Polygon({ vertices: [[cx, binBottomY, 0], [cx + s, binBottomY, 0]], color: YELLOW });
      seg.setStrokeWidth(3).setFillOpacity(0);
      scene.add(seg); boardObjs.push(seg); curveSegs.push(seg);
    }
  }

  updateBars();
  updateCountText();
}

// ---- Histogram + theoretical curve update ----
function updateBars() {
  let maxC = 1;
  for (const c of counts) if (c > maxC) maxC = c;
  scaleY = barAreaH / Math.max(maxC, 8);
  for (let k = 0; k <= nRows; k++) {
    const cx = (k - nRows / 2) * s;
    const h = counts[k] * scaleY;
    bars[k].setVertices([[cx - 0.42 * s, binBottomY, 0], [cx + 0.42 * s, binBottomY, 0], [cx + 0.42 * s, binBottomY + h, 0], [cx - 0.42 * s, binBottomY + h, 0]]);
  }
  for (let k = 0; k < nRows; k++) {
    const ya = binBottomY + totalLanded * probs[k] * scaleY;
    const yb = binBottomY + totalLanded * probs[k + 1] * scaleY;
    curveSegs[k].setVertices([[(k - nRows / 2) * s, ya, 0], [(k + 1 - nRows / 2) * s, yb, 0]]);
  }
}

// ---- Ball lifecycle ----
const ballColors = [RED, ORANGE, YELLOW, GREEN, PURPLE, PINK || RED, TEAL];
function spawnBall() {
  const dot = new Dot({ radius: 0.075, color: ballColors[Math.floor(Math.random() * ballColors.length)] });
  const wps = [[0, y1 + 0.8, 0], [0, y1, 0]];
  let x = 0;
  for (let r = 1; r <= nRows; r++) {
    x += (Math.random() < 0.5 ? -1 : 1) * s / 2;
    if (r < nRows) wps.push([x, y1 - r * rowH, 0]);
  }
  const bin = Math.round(x / s + nRows / 2);
  const landY = binBottomY + Math.min(counts[bin] * scaleY, barAreaH) + 0.12;
  wps.push([x, landY, 0]);
  const durs = [];
  for (let i = 0; i < wps.length - 1; i++) {
    const dx = wps[i + 1][0] - wps[i][0], dy = wps[i + 1][1] - wps[i][1];
    durs.push(Math.sqrt(dx * dx + dy * dy) / ballSpeed());
  }
  dot.moveTo(wps[0]);
  scene.add(dot);
  balls.push({ dot, wps, durs, seg: 0, t: 0, bin });
}

function landBall(b, idx) {
  scene.remove(b.dot);
  balls.splice(idx, 1);
  counts[b.bin]++;
  totalLanded++;
  updateBars();
  updateCountText();
}

function stepSim() {
  const now = performance.now();
  if (lastTime === null) { lastTime = now; return; }
  let dt = (now - lastTime) / 1000;
  lastTime = now;
  if (dt > 0.06) dt = 0.06;

  if (running) {
    spawnTimer -= dt;
    if (spawnTimer <= 0) {
      if (balls.length < 28) spawnBall();
      spawnTimer = 0.35 / speed;
    }
  }

  for (let i = balls.length - 1; i >= 0; i--) {
    const b = balls[i];
    b.t += dt;
    while (b.seg < b.durs.length - 1 && b.t >= b.durs[b.seg]) {
      b.t -= b.durs[b.seg];
      b.seg++;
    }
    if (b.seg === b.durs.length - 1 && b.t >= b.durs[b.seg]) {
      landBall(b, i);
      continue;
    }
    const tt = b.t / b.durs[b.seg];
    const p0 = b.wps[b.seg], p1 = b.wps[b.seg + 1];
    const hop = (b.seg >= 1 && b.seg <= b.wps.length - 3) ? 0.07 * Math.sin(Math.PI * tt) : 0;
    b.dot.moveTo([p0[0] + (p1[0] - p0[0]) * tt, p0[1] + (p1[1] - p0[1]) * tt + hop, 0]);
  }
}

// ---- Intro ----
await scene.play(new Write(title));
await scene.play(new FadeIn(subtitle));
await scene.play(new Write(formula));

rebuildBoard();

// Hidden driver that runs the physics every frame
const driver = new Dot({ point: [6.6, -3.7, 0], radius: 0.03, color: BLACK });
scene.add(driver);
driver.addUpdater(() => { stepSim(); });

// ---- Controls ----
const controls = new Controls(scene, { position: 'top-right', width: 240 });
controls.addSlider({ label: 'Rows (n)', min: 4, max: 12, value: 8, step: 1, onChange: (v) => { nRows = v; rebuildBoard(); } });
controls.addSlider({ label: 'Speed', min: 0.5, max: 4, value: 1.5, step: 0.1, onChange: (v) => { speed = v; } });
controls.addButton({ label: 'Start / Pause', onClick: () => { running = !running; } });
controls.addButton({ label: 'Drop one ball', onClick: () => { spawnBall(); } });
controls.addButton({ label: 'Reset', onClick: () => { rebuildBoard(); } });

running = true;
await scene.wait(999999);"}

